// Kill switch + janela + parâmetros. Tudo num nó só para abortar cedo e barato.
let cfgRaw = null;
try { cfgRaw = $input.first().json; } catch (e) { cfgRaw = null; }
const cfg = (Array.isArray(cfgRaw) ? cfgRaw[0] : cfgRaw)?.valor || {};

const ativo = cfg.ativo !== false;            // default ligado só se a chave existir
const modoTeste = cfg.modo_teste === true;
const numeroTeste = String(cfg.numero_teste || '');
const limiteDiario = Number(cfg.limite_diario ?? 10);

if (modoTeste && !numeroTeste) throw new Error('modo_teste=true mas numero_teste não configurado — abortando por segurança');

// Janela 8h–18h seg–sex (São Paulo = UTC-3, sem horário de verão)
const sp = new Date(Date.now() - 3 * 3600 * 1000);
const dia = sp.getUTCDay();
const hora = sp.getUTCHours();
const dentroJanela = dia >= 1 && dia <= 5 && hora >= 8 && hora < 18;

const prosseguir = ativo && dentroJanela;

return [{ json: {
  prosseguir,
  motivo_parada: !ativo ? 'kill_switch' : (!dentroJanela ? 'fora_da_janela' : null),
  modo_teste: modoTeste,
  numero_teste: numeroTeste,
  limite_diario: limiteDiario,
  hoje_sp: sp.toISOString().slice(0, 10)
} }];

// Cota: conta interações msg1 de HOJE (fonte correta — corrige o bug do v3.1
// que contava por empresas.criado_em). msg1_teste não entra (etapa diferente).
const ctx = $('Checar Kill Switch + Janela').first().json;
let enviados = 0;
try {
  enviados = $input.all().map(i => i.json).flat().filter(j => j && j.id !== undefined).length;
} catch (e) { enviados = 0; }
const temCota = enviados < ctx.limite_diario;
return [{ json: { ...ctx, enviados_hoje: enviados, tem_cota: temCota } }];

// Valida se veio lead (fila pode estar vazia)
const itens = $input.all().map(i => i.json).flat().filter(l => l && l.id);
if (itens.length === 0) return [{ json: { __vazio: true } }];
const ctx = $('Calcular Cota').first().json;
return [{ json: { lead: itens[0], ctx } }];

// O claim é a proteção anti-duplicata: o PATCH só afeta a linha se ela AINDA
// estiver com status='fila'. Se outra execução chegou primeiro, a resposta vem
// vazia — e esta execução aborta sem enviar nada.
const resp = $input.all().map(i => i.json).flat().filter(r => r && r.id);
const base = $('Preparar Lead').first().json;
if (resp.length === 0) return [{ json: { __claim_falhou: true } }];
return [{ json: { lead: base.lead, ctx: base.ctx } }];

const base = $('Claim OK?').first().json;
const lead = base.lead;
let roteiros = [];
try { roteiros = $input.all().map(i => i.json).flat(); } catch (e) { roteiros = []; }
const roteiro = roteiros.find(r => r.perfil_oferta === lead.perfil_oferta) || null;
return [{ json: { lead, ctx: base.ctx, roteiro } }];

// Valida a mensagem (mesmas regras do v3.1) e resolve o DESTINO:
// modo_teste=true => numero_teste, senão o WhatsApp real do lead.
const base = $('Juntar Lead + Roteiro').first().json;
const lead = base.lead;
const ctx = base.ctx;

let texto = null;
try {
  texto = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
} catch (e) { texto = null; }

const PROIBIDAS = /\b(gr[aá]tis|promo[cç][aã]o|imperd[ií]vel|desconto|urgente|oportunidade [uú]nica)\b/i;
const TEM_LINK = /https?:\/\/|www\./i;
const valido = !!texto && !TEM_LINK.test(texto) && !PROIBIDAS.test(texto)
  && texto.length >= 60 && texto.length <= 700 && /\?/.test(texto);

const FALLBACK = ('Oi, ' + (lead.nome_socio || '') + '! Tudo bem? Vi a ' + lead.nome_exibicao + ' aqui em ' + lead.municipio + ' e reparei em algumas coisas na presenca digital de voces que podem estar deixando clientes pelo caminho. Posso te mostrar rapidinho o que encontrei?').replace(/\s+/g, ' ').trim();

const mensagem = valido ? texto : FALLBACK;
const destino = ctx.modo_teste ? ctx.numero_teste : String(lead.whatsapp || '');
if (!destino) throw new Error('Lead sem WhatsApp — abortando (lead ' + lead.slug + ' fica em status abordando para revisão)');

// Delay humano aleatório: 60s a 40min antes do envio
const delaySegundos = 60 + Math.floor(Math.random() * 2340);
//const delaySegundos = 30; // T-D1: delay curto só para teste — REVERTER depois

return [{ json: {
  lead, ctx, mensagem,
  copy_fallback: !valido,
  destino,
  etapa: ctx.modo_teste ? 'msg1_teste' : 'msg1',
  delay_segundos: delaySegundos
} }];

// Interpreta o resultado do envio. NUNCA faz retry — falha vai para o branch de alerta.
const prep = $('Validar + Resolver Destino').first().json;
const resp = $input.first().json || {};
const evolutionId = resp?.key?.id || null;
const enviou = !!evolutionId;
return [{ json: { ...prep, enviou, evolution_id: evolutionId, resposta_envio: enviou ? null : JSON.stringify(resp).slice(0, 400) } }];

